SELECT gen_random_uuid()::text, 'formula', '$N = N_0e^{rt}$', 'Population Growth', '$\text{exponential: } N = N_0e^{rt},\ t_d = \frac{\ln 2}{r} \approx \frac{70}{r\%};\qquad \text{logistic: } \frac{dN}{dt} = rN\left(1 - \frac{N}{K}\right)$', NULL, 'How a population grows: without limit (exponential), or levelling off at what the environment can support (logistic).', '[{"symbol":"$N_0$","meaning":"starting population","unit":null},{"symbol":"$r$","meaning":"growth rate","unit":"$\\text{1/yr}$"},{"symbol":"$K$","meaning":"carrying capacity","unit":null}]'::jsonb, 'The rule of 70: 2% growth doubles a population in about 35 years.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Environmental Science & Engineering' AND t."subject" = 'ESAS' AND s."normKey" = 'natural systems and resources' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Environmental Science & Engineering' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
