SELECT gen_random_uuid()::text, 'formula', '$T = \frac{1}{r}\ln\left(\frac{rR}{C_0} + 1\right)$', 'Lifetime of a Resource', '$\text{static: } T = \frac{R}{C_0};\qquad \text{growing use: } T = \frac{1}{r}\ln\left(\frac{rR}{C_0} + 1\right)$', '$\text{yr}$', 'How long a non-renewable reserve lasts at today''s use, and if use keeps growing.', '[{"symbol":"$R$","meaning":"known reserves","unit":null},{"symbol":"$C_0$","meaning":"present yearly use","unit":null},{"symbol":"$r$","meaning":"growth rate of use","unit":"$\\text{1/yr}$"}]'::jsonb, 'Growing demand shortens it drastically: 100 years of reserves at 2% growth last only 55 years.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Environmental Science & Engineering' AND t."subject" = 'ESAS' AND s."normKey" = 'natural systems and resources' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Environmental Science & Engineering' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
