SELECT gen_random_uuid()::text, 'formula', '$D_t$', 'Streeter-Phelps Oxygen Sag', '$D_t = \frac{k_1L_0}{k_2 - k_1}\left(e^{-k_1t} - e^{-k_2t}\right) + D_0e^{-k_2t}$', '$\text{mg/L}$', 'The dissolved-oxygen deficit downstream of a waste discharge: microbes use oxygen while the air puts it back.', '[{"symbol":"$L_0$","meaning":"ultimate BOD after mixing","unit":"$\\text{mg/L}$"},{"symbol":"$k_1, k_2$","meaning":"deoxygenation and reaeration rates","unit":"$\\text{1/day}$"},{"symbol":"$D_0$","meaning":"initial oxygen deficit","unit":"$\\text{mg/L}$"},{"symbol":"$t$","meaning":"travel time downstream","unit":"$\\text{days}$"}]'::jsonb, 'Critical time: t_c = ln[(k₂/k₁)(1 − D₀(k₂ − k₁)/(k₁L₀))]/(k₂ − k₁). Fish need about 5 mg/L.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Environmental Science & Engineering' AND t."subject" = 'ESAS' AND s."normKey" = 'water pollution' AND s."active"), NULL, false, 'PENDING', now(), now()
